/-- The selected propensity obeys the one-tenth Holder modulus with radius three. -/
def PropensityHolder : Prop :=
  ∀ x x', |P.e x - P.e x'| ≤ L * |(x : ℝ) - x'| ^ (1/10 : ℝ) -- @realizes e(Holder 1/10 radius 3)

