/-- The selected control regression obeys the one-tenth Holder modulus with radius three. -/
def ControlHolder : Prop :=
  ∀ x x', |P.mu0 x - P.mu0 x'| ≤ L * |(x : ℝ) - x'| ^ (1/10 : ℝ) -- @realizes mu0(Holder radius 3)

