/-- The selected contrast obeys the Lipschitz modulus with radius three. -/
def ContrastLipschitz : Prop :=
  ∀ x x', |tau P x - tau P x'| ≤ L * |(x : ℝ) - x'| -- @realizes tau(Lipschitz radius 3)

