/-- Coverage is the probability that the randomized coded interval contains the law-specific point
target. -/
def coverage (I : Kernel (Dataset n) IntervalCode) (P : CausalLaw) : ℝ :=
  (I ∘ₘ dataLaw n P).real {c | theta P ∈ c.toSet}

