/-- Maximal absolute risk is the extended-real supremum across the complete law class. -/
def worstRisk (T : Kernel (Dataset n) ℝ) : ℝ≥0∞ :=
  ⨆ P, ⨆ (_ : CompleteModel P), scalarRisk n T P

