/-- Maximal expected length is the extended-real supremum across the complete law class. -/
def worstLength (I : Kernel (Dataset n) IntervalCode) : ℝ≥0∞ :=
  ⨆ P, ⨆ (_ : CompleteModel P), expectedLength n I P
